-- Separate Academy lessons for the Complete Human Learning Arc.

WITH new_paths(slug, local_order, title, purpose, coverage, namespace_name) AS (
  VALUES
  ('human-learning-arc', 1, 'The Complete Human Learning Arc', 'Start at Zero. Explore 48 distinct modules and the original 101 Hands-On Learning Methods.', 'Before the cave; cave and open-air records; settlement and transmission; apprenticeship; digital systems; future scenarios.', 'tabor-academy-way-human-learning-arc-dev'),
  ('human-arc-early', 2, 'Before the Cave & Inside the Cave', 'Explore fossils, stone tools, senses, shelter, and teaching through speech. Caves preserve some records especially well. Open-air sites document other parts of the story.', 'Deep time · open-air camps · shelters', 'tabor-academy-way-human-arc-early-dev'),
  ('human-arc-ancient', 3, 'Ancient & Biblical', 'Explore water, food, materials, trade, and memory. Food production and writing developed across distinct places and times. Oral collections and KJV study have their own contexts and sources.', 'Settlements · oral traditions · records', 'tabor-academy-way-human-arc-ancient-dev'),
  ('human-arc-mechanical', 4, 'Guild & Mechanical', 'Follow forces and energy through joints, gears, and systems people built and repaired. Compare who could reproduce a process when instructions moved between people.', 'Apprenticeship · models · repair', 'tabor-academy-way-human-arc-mechanical-dev'),
  ('human-arc-digital', 5, 'Digital & Edge', 'Follow a message, record, or AI claim through local systems. Check what survives a broken link and what evidence establishes the original source.', 'Networks · evidence · recovery', 'tabor-academy-way-human-arc-digital-dev'),
  ('human-arc-future', 6, 'Sovereign Future', 'Start with an outcome and look for its dependencies. These stations use designed scenarios with testable assumptions and more than one possible future.', 'Scenarios · resources · options', 'tabor-academy-way-human-arc-future-dev')
)
SELECT slug, (SELECT COALESCE(MAX(position), 0) FROM academy_way_paths) + local_order,
  title, purpose, coverage, namespace_name
FROM new_paths
WHERE true
ON CONFLICT(slug) DO NOTHING;

ON CONFLICT(slug) DO NOTHING;
