INSERT INTO academy_way_paths (slug, position, title, purpose, coverage, namespace_name)
INSERT INTO academy_way_missions (slug, path, position, title, outcome, build, flip, integrate, verify, link) VALUES
  ('human-learning-arc-zero', 'human-learning-arc', 400, '0 · Start from the evidence', 'Make a timeline card with a place, evidence type, approximate date or scenario, and one question.', 'Choose a trace, a record, a working model, or a proposed future. Write down what you want to find out.', 'Separate an observation from an interpretation. Mark approximate dates and label proposed futures as scenarios.', 'Use the five era links to move forward. Start with a model of a finished outcome to work backward. Compare your work with the separate 101 Hands-On Learning Methods.', 'Ask a second learner to identify which claims are supported now, which can be tested, and which remain open.', 'institution/learning-methods/'),
  ('human-learning-arc-early', 'human-learning-arc', 401, 'Before the Cave & Inside the Cave', 'Explore fossils, stone tools, senses, shelter, and teaching through speech. Caves preserve some records especially well. Open-air sites document other parts of the story.', 'Pick an activity in this section and write down the material, archive, or example you will use.', 'Mark the place and setting. Keep observation, historical inference and personal design choices identifiable.', 'Do a module and trace a connection to a different era. If the same skill appears twice, record how its purpose changes.', 'Carry one checked result back to your timeline card.', 'way/human-arc-early/'),
  ('human-learning-arc-ancient', 'human-learning-arc', 402, 'Ancient & Biblical', 'Explore water, food, materials, trade, and memory. Food production and writing developed across distinct places and times. Oral collections and KJV study have their own contexts and sources.', 'Pick an activity in this section and write down the material, archive, or example you will use.', 'Mark the place and setting. Keep observation, historical inference and personal design choices identifiable.', 'Do a module and trace a connection to a different era. If the same skill appears twice, record how its purpose changes.', 'Carry one checked result back to your timeline card.', 'way/human-arc-ancient/'),
  ('human-learning-arc-mechanical', 'human-learning-arc', 403, 'Guild & Mechanical', 'Follow forces and energy through joints, gears, and systems people built and repaired. Compare who could reproduce a process when instructions moved between people.', 'Pick an activity in this section and write down the material, archive, or example you will use.', 'Mark the place and setting. Keep observation, historical inference and personal design choices identifiable.', 'Do a module and trace a connection to a different era. If the same skill appears twice, record how its purpose changes.', 'Carry one checked result back to your timeline card.', 'way/human-arc-mechanical/'),
  ('human-learning-arc-digital', 'human-learning-arc', 404, 'Digital & Edge', 'Follow a message, record, or AI claim through local systems. Check what survives a broken link and what evidence establishes the original source.', 'Pick an activity in this section and write down the material, archive, or example you will use.', 'Mark the place and setting. Keep observation, historical inference and personal design choices identifiable.', 'Do a module and trace a connection to a different era. If the same skill appears twice, record how its purpose changes.', 'Carry one checked result back to your timeline card.', 'way/human-arc-digital/'),
  ('human-learning-arc-future', 'human-learning-arc', 405, 'Sovereign Future', 'Start with an outcome and look for its dependencies. These stations use designed scenarios with testable assumptions and more than one possible future.', 'Pick an activity in this section and write down the material, archive, or example you will use.', 'Mark the place and setting. Keep observation, historical inference and personal design choices identifiable.', 'Do a module and trace a connection to a different era. If the same skill appears twice, record how its purpose changes.', 'Carry one checked result back to your timeline card.', 'way/human-arc-future/'),
  ('human-arc-method-31', 'human-arc-early', 406, '31. Before the Cave · Deep Time and Hominin Evidence', 'Complete the fossils and stone tools on separate timelines exercise. Record evidence that a partner can check.', 'Set up: Fossils and stone tools on separate timelines. Ask: Which dates are from finds, and which dates are inferences?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Build a paper timeline using published Lomekwi and human-origins sources. Mark fossil, artifact and estimate in different shapes and include the dates as reported by each source.', 'A stone tool date anchors a find, and a species attribution needs its own evidence. Allow ranges and overlapping lineages.', 'way/human-arc-early/human-arc-method-32/'),
  ('human-arc-method-32', 'human-arc-early', 407, '32. Open-Air Camps, Rockshelters & Cave Records', 'Complete the three archaeological site plans exercise. Record evidence that a partner can check.', 'Set up: Three archaeological site plans. Ask: Which materials are more likely to survive in each setting?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Sort sample data from open-air, rockshelter and cave samples. Correlate what people may have left with what the soil, moisture and excavation might preserve.', 'Surviving cave evidence is one sample of how people lived. Missing evidence can reflect preservation or search conditions.', 'way/human-arc-early/human-arc-method-34/'),
  ('human-arc-method-34', 'human-arc-early', 408, '34. Migration, Changing Climate & Lost Coastlines', 'Complete the past and present coastline maps exercise. Record evidence that a partner can check.', 'Set up: Past and present coastline maps. Ask: What changes when the shoreline moves?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Overlay an older coastline on a modern map with tracing paper. Compare possible routes and where sites might be buried or submerged. Mark which parts are hypotheses.', 'Routes need evidence of their own. A vanished land area can explain missing opportunities for discovery without proving a particular route.', 'way/human-arc-early/human-arc-method-35/'),
  ('human-arc-method-35', 'human-arc-early', 409, '35. Care, Kinship & Cooperative Learning', 'Complete the a shared shelter and teaching plan exercise. Record evidence that a partner can check.', 'Set up: A shared shelter and teaching plan. Ask: Which evidence could show cooperation, and which role is a modern guess?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Assign civilian roles in a fictional camp and sketch how a method is taught across generations. Compare the model with a museum example of a preserved dwelling or shared activity.', 'The model shows how cooperation could function. It keeps the inferred roles separate from the artifact or site evidence.', 'way/human-arc-early/human-arc-method-01/'),
  ('human-arc-method-01', 'human-arc-early', 410, '1. Primal Breath & Cold-Shock Regulation (Pre-Cave)', 'Complete the cold-water scenario card exercise. Record evidence that a partner can check.', 'Set up: Cold-water scenario card. Ask: Which choices reduce exposure before a person gets wet?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare two illustrated journeys in cold rain. Design a dry-route decision tree with shelter, dry layers and a contact check. Discuss normal breathing at room temperature using the paper scenario.', 'The safer route limits exposure, keeps a dry exit available and records whom to contact. The historical record does not date a specific breathing practice to a pre-cave era.', 'way/human-arc-early/human-arc-method-02/'),
  ('human-arc-method-02', 'human-arc-early', 411, '2. Ground Vibration & Footstep Listening', 'Complete the cup-and-table vibration station exercise. Record evidence that a partner can check.', 'Set up: Cup-and-table vibration station. Ask: Which parts of the table carry a detectable tap?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Set a cup on a desk and tap the desk softly from three marked positions. Predict which taps will make the water surface move. Ask a partner to record observations with eyes open, then change one variable.', 'A repeated movement can show vibration traveled through that setup. Range, sound source, and outdoor conditions need separate evidence.', 'way/human-arc-early/human-arc-method-03/'),
  ('human-arc-method-03', 'human-arc-early', 412, '3. Scent Tracking & Wind Reading', 'Complete the wind arrow and cue cards exercise. Record evidence that a partner can check.', 'Set up: Wind arrow and cue cards. Ask: Which way could a cue travel, and what else could explain it?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Use paper arrows to mark air movement from a small fan. Move three imaginary scent-source cards and trace where a signal might travel. Record competing explanations for each reading.', 'The best map distinguishes wind direction from the location or identity of a source. Treat smell and wind as limited cues.', 'way/human-arc-early/human-arc-method-04/'),
  ('human-arc-method-04', 'human-arc-early', 413, '4. Flint Knapping & Stone Tool Percussion (Cave Era)', 'Complete the stone-tool photographs and clay fracture model exercise. Record evidence that a partner can check.', 'Set up: Stone-tool photographs and clay fracture model. Ask: What can a surviving flake tell you about a strike?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare published photos of stone cores and flakes. Sketch a potential force direction on each. Model fracture patterns using breakaway modeling clay and compare the shapes with the photographs.', 'Mark the observed features separately from your proposal about force. Toolmaking evidence at Lomekwi is about 3.3 million years old and predates Homo sapiens.', 'way/human-arc-early/human-arc-method-05/'),
  ('human-arc-method-05', 'human-arc-early', 414, '5. Cave Wall Pigment & Ochre Storytelling', 'Complete the paper rock-art panel exercise. Record evidence that a partner can check.', 'Set up: Paper rock-art panel. Ask: Can a second person distinguish the image from your interpretation?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Make three marks on rough paper with washable art materials. Attach a short log stating which marks are intentional. Compare a photograph from an archaeological collection and label the possibilities the record leaves open.', 'The paper scene comes with your explanation. The archaeological image has its own context, and a claim such as a star map needs specific evidence.', 'way/human-arc-early/human-arc-method-06/'),
  ('human-arc-method-06', 'human-arc-early', 415, '6. Acoustic Echo-Location in Caverns', 'Complete the cardboard sound paths exercise. Record evidence that a partner can check.', 'Set up: Cardboard sound paths. Ask: What changes when the boundary moves?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Clap at ordinary volume in two familiar indoor spaces, or compare two recordings. Draw possible reflection paths and identify one change in the room that could affect the result.', 'A repeated or prolonged sound can support a reflection hypothesis. Room geometry and material properties need further measurements.', 'way/human-arc-early/human-arc-method-07/'),
  ('human-arc-method-07', 'human-arc-early', 416, '7. Cordage, Sinew & Knot Engineering', 'Complete the three tabletop yarn samples exercise. Record evidence that a partner can check.', 'Set up: Three tabletop yarn samples. Ask: Which sample keeps its shape under the same small load?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare loose yarn, twisted yarn and a simple braided sample. Test each with the same small paperclip load over a tabletop. Record stretch rather than trying to reach a breaking point.', 'A usable comparison keeps the material, starting length and weight consistent. These samples illustrate small loads only.', 'way/human-arc-early/human-arc-method-08/'),
  ('human-arc-method-08', 'human-arc-early', 417, '8. Shelter Geometry & Earth Insulation', 'Complete the two miniature shelters exercise. Record evidence that a partner can check.', 'Set up: Two miniature shelters. Ask: Which shape cuts airflow, and which changes heat loss?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Build two paper models for a fan test. Use two identical cups with equal amounts of teacher-prepared warm water. Wrap only one cup and compare their temperatures after the same interval.', 'Record wind and temperature as separate outcomes. A useful test changes one construction feature and compares the same length of time.', 'way/human-arc-early/human-arc-method-09/'),
  ('human-arc-method-09', 'human-arc-early', 418, '9. Foraging & Poison-Antidote Discrimination', 'Complete the plant lookalike photograph set exercise. Record evidence that a partner can check.', 'Set up: Plant lookalike photograph set. Ask: Which details would an expert need to tell the specimens apart?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare photographs in a regional field guide. Make a table for leaf pattern, habitat, lookalikes, and unresolved ID. Assign every unknown or lookalike the same action: leave it in place and ask a qualified expert.', 'A reliable worksheet marks uncertainty and uses photographs rather than taste, touch tests, or a proposed antidote.', 'way/human-arc-early/human-arc-method-10/'),
  ('human-arc-method-10', 'human-arc-early', 419, '10. Persistence Hunting & Endurance Tracking', 'Complete the tabletop trail of tracks exercise. Record evidence that a partner can check.', 'Set up: Tabletop trail of tracks. Ask: How many routes remain plausible from this set of clues?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Arrange paper track, rainfall and broken-twig cards on a mock map. Compare two possible routes and place a rest-and-water marker on a fictional observer''s journey.', 'Directional evidence and species ID are separate questions. The route stays hypothetical where multiple paths fit.', 'way/human-arc-early/human-arc-method-11/'),
  ('human-arc-method-11', 'human-arc-early', 420, '11. Bone, Antler & Ivory Carving', 'Complete the artifact shapes in soft clay exercise. Record evidence that a partner can check.', 'Set up: Artifact shapes in soft clay. Ask: Which details support a proposed use?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare museum images of an eyed needle, a flute and a worked fragment. Recreate the visible outline in soft clay. Sort observed features and proposed functions into two columns.', 'A feature such as an eye or repeated holes supports a comparison, but missing context or wear evidence can leave function open.', 'way/human-arc-early/human-arc-method-12/'),
  ('human-arc-method-12', 'human-arc-early', 421, '12. Tribal Fire-Circle Oral Transmission', 'Complete the two retellings of a fictional message exercise. Record evidence that a partner can check.', 'Set up: Two retellings of a fictional message. Ask: Which parts survive both routes through the group?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Write a three-line fictional weather message. Tell it to two separate groups and compare both final versions. Choose a repeating cue and rerun the exercise.', 'The record keeps the original and the retellings side by side. Respect the authority and permissions of living communities when discussing actual traditions.', 'way/human-arc-early/human-arc-method-33/'),
  ('human-arc-method-33', 'human-arc-early', 422, '33. Fire, Hearths & Food Transformation', 'Complete the illustrated hearth evidence cards exercise. Record evidence that a partner can check.', 'Set up: Illustrated hearth evidence cards. Ask: Which observations would strengthen a hearth interpretation?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare fictional soil cards with ash, altered stone, a repeated layer or a natural burn. Sort each as observed, inferred or unknown. Use a Smithsonian account to check terminology.', 'A more persuasive hearth case uses multiple lines of evidence and considers natural fire. The classroom activity uses pictures and paper.', 'way/human-learning-arc/'),
  ('human-arc-method-36', 'human-arc-ancient', 423, '36. Water, Storage & the First Settlements', 'Complete the water-and-grain ledger exercise. Record evidence that a partner can check.', 'Set up: Water-and-grain ledger. Ask: How does a seasonal shortfall change the storage plan?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Use marked cups or tokens to model water and food storage over two seasons. Lose one supply source during a trial and make a new allocation plan.', 'Inputs, storage losses and withdrawals balance. Label which choices are simulation values and which claims would require local archaeological evidence.', 'way/human-arc-ancient/human-arc-method-37/'),
  ('human-arc-method-37', 'human-arc-ancient', 424, '37. Agriculture in More Than One Place', 'Complete the world map of documented food systems exercise. Record evidence that a partner can check.', 'Set up: World map of documented food systems. Ask: What changes when three regions are placed on parallel tracks?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare examples of wheat in Southwest Asia, maize in Mesoamerica, and rice in East Asia. Plot their ranges by location and label factors such as domestication, gathering and exchange separately.', 'A good map allows independently developing or interacting food systems and keeps dates specific to their region and source.', 'way/human-arc-ancient/human-arc-method-38/'),
  ('human-arc-method-38', 'human-arc-ancient', 425, '38. Textiles, Pottery & Material Memory', 'Complete the weave diagram and pottery photographs exercise. Record evidence that a partner can check.', 'Set up: Weave diagram and pottery photographs. Ask: What can a surviving imprint or fragment preserve?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Use paper strips for a weave and compare it with a photographed clay impression or fragment. Record which features can still be measured when the original material decays.', 'A pattern can sometimes survive as an impression. The finished object and its use need additional evidence.', 'way/human-arc-ancient/human-arc-method-39/'),
  ('human-arc-method-39', 'human-arc-ancient', 426, '39. Counting, Trade & the Origins of Writing', 'Complete the tokens, tally marks and a ledger exercise. Record evidence that a partner can check.', 'Set up: Tokens, tally marks and a ledger. Ask: What changes when the person who made a record leaves?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Track five fictional exchanges with tokens, then rewrite them as a tally and a labeled record. Ask someone outside the group to reconstruct the transactions.', 'A transferable record identifies quantities, units and participants. Writing traditions and dates are compared within their own documented regions.', 'way/human-arc-ancient/human-arc-method-40/'),
  ('human-arc-method-40', 'human-arc-ancient', 427, '40. Living Oral Traditions & Ocean Wayfinding', 'Complete the environment cue cards and a route sketch exercise. Record evidence that a partner can check.', 'Set up: Environment cue cards and a route sketch. Ask: Which navigation cues were passed on by practiced instruction?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Read UNESCO''s Carolinian wayfinding entry. Map three possible environmental cues from the account and distinguish living practice from a fossil or artifact inference.', 'The record names a continuing Micronesian tradition and its teaching context. The paper map uses cues as examples instead of claiming a reconstructed voyage.', 'way/human-arc-ancient/human-arc-method-41/'),
  ('human-arc-method-41', 'human-arc-ancient', 428, '41. Roads, Waterworks & Shared Services', 'Complete the model town infrastructure map exercise. Record evidence that a partner can check.', 'Set up: Model town infrastructure map. Ask: Which stop fails first when water access is interrupted?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Lay out a paper town with paths, water collection, storage and waste paths. Set a route out of service and trace who is affected and how the system recovers.', 'The repair plan addresses upstream and downstream effects and documents access to the restored service.', 'way/human-learning-arc/'),
  ('human-arc-method-13', 'human-arc-mechanical', 429, '13. Blacksmithing & Metallurgy Forging', 'Complete the metallurgy diagram and material samples exercise. Record evidence that a partner can check.', 'Set up: Metallurgy diagram and material samples. Ask: Which property is the chart measuring?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare two classroom charts of hardness and toughness. Use labeled craft samples to explain why a hinge and a spring may have different priorities. Trace one manufacturing stage on paper.', 'Your explanation connects the chosen property to the part''s job. Heating and tempering are studied through diagrams or recorded demonstrations.', 'way/human-arc-mechanical/human-arc-method-14/'),
  ('human-arc-method-14', 'human-arc-mechanical', 430, '14. Joinery Without Nails or Glue', 'Complete the cardboard joint models exercise. Record evidence that a partner can check.', 'Set up: Cardboard joint models. Ask: Which joint resists pulling apart in the tested direction?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Cut teacher-prepared card slots or use interlocking blocks to model two joints. Pull each gently with the same small load in two directions and record when it slides.', 'Joint geometry and the direction of force both matter. State which direction the joint was designed to resist.', 'way/human-arc-mechanical/human-arc-method-15/'),
  ('human-arc-method-15', 'human-arc-mechanical', 431, '15. Waterwheel, Windmill & Gear Ratios', 'Complete the hand-driven gear pair exercise. Record evidence that a partner can check.', 'Set up: Hand-driven gear pair. Ask: What happens to output turns when the gear sizes change?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Turn a classroom gear model by hand. Count input and output turns for two gear pairs. Sketch how a windmill or waterwheel could supply an input.', 'A 12-tooth driver turning a 24-tooth driven gear gives one output turn for two input turns in the simple model.', 'way/human-arc-mechanical/human-arc-method-16/'),
  ('human-arc-method-16', 'human-arc-mechanical', 432, '16. Masonry, Mortar & Arch Load Physics', 'Complete the foam-block arch and paper supports exercise. Record evidence that a partner can check.', 'Set up: Foam-block arch and paper supports. Ask: What happens if one support can move sideways?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Assemble a small arch from foam blocks over a tabletop. Draw the sideways thrust at each side. Compare the model with and without fixed side supports using a light paper load.', 'The model can spread under load if its support moves. An arch depends on geometry, material and adequate abutments.', 'way/human-arc-mechanical/human-arc-method-17/'),
  ('human-arc-method-17', 'human-arc-mechanical', 433, '17. Analog Navigation (Sextant, Compass & Dead Reckoning)', 'Complete the paper chart and simulated bearings exercise. Record evidence that a partner can check.', 'Set up: Paper chart and simulated bearings. Ask: How far can a small error move your plotted position?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Plot two legs from supplied compass bearings and speeds on a paper chart. Add drift as a separate arrow. Compare an instructor-provided angle observation with your estimate.', 'Distance is speed times time with consistent units. The final position is an estimate with a visible uncertainty or drift allowance.', 'way/human-arc-mechanical/human-arc-method-18/'),
  ('human-arc-method-18', 'human-arc-mechanical', 434, '18. Small-Engine & Carburetor Diagnostics', 'Complete the mock worksheet for engine symptoms exercise. Record evidence that a partner can check.', 'Set up: Mock worksheet for engine symptoms. Ask: Which observation rules out one proposed cause?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Use a cutaway diagram and three simulated fault cards. Sort the evidence by fuel, ignition, and compression. Choose an observation to distinguish two hypotheses.', 'Results justify the next hypothesis. The exercise uses diagrams and a stationary demonstration model with the facilitator able to see and supervise.', 'way/human-arc-mechanical/human-arc-method-19/'),
  ('human-arc-method-19', 'human-arc-mechanical', 435, '19. Electrical Wiring, Circuits & Soldering', 'Complete the battery classroom circuit diagram exercise. Record evidence that a partner can check.', 'Set up: Battery classroom circuit diagram. Ask: Where is the shared path in the two layouts?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Use an approved low-voltage classroom kit or a simulator to compare a lamp in series and parallel. Mark the closed path and predict what happens when one simulated component is removed.', 'In the parallel model, opening one branch can leave another complete. Keep the exercise to the classroom kit or simulation.', 'way/human-arc-mechanical/human-arc-method-20/'),
  ('human-arc-method-20', 'human-arc-mechanical', 436, '20. Radio Wave & Morse Code Transmission', 'Complete the printed morse card and led simulator exercise. Record evidence that a partner can check.', 'Set up: Printed Morse card and LED simulator. Ask: How much meaning changes when spacing changes?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Send a short fictional message by tapping or using a simulator. Change one gap and ask a partner to decode both versions. Compare the results.', 'Dots, dashes and distinct gaps carry the message. The sender and receiver can identify which spacing error changed it.', 'way/human-arc-mechanical/human-arc-method-42/'),
  ('human-arc-method-42', 'human-arc-mechanical', 437, '42. Apprenticeship, Printing & Widely Shared Instructions', 'Complete the one recipe transmitted in three ways exercise. Record evidence that a partner can check.', 'Set up: One recipe transmitted in three ways. Ask: Which version can a new learner reproduce most reliably?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Give three groups the same fictional assembly sequence by demonstration, one handwritten page and identical printed copies. Compare the errors and time needed to relay it.', 'The experiment describes what changed under these conditions. Use it to pose a historical question about apprenticeship or printing, with dates stated by region.', 'way/human-arc-mechanical/human-arc-method-43/'),
  ('human-arc-method-43', 'human-arc-mechanical', 438, '43. Standard Measures, Parts & Repair Networks', 'Complete the inventory cards and mismatched spacers exercise. Record evidence that a partner can check.', 'Set up: Inventory cards and mismatched spacers. Ask: Which tolerance determines whether two parts fit?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Build paper templates with three named dimensions. Have partners make matching parts separately, then swap and record fits and mismatches.', 'Record reference units and tolerance. Identical names on parts do not establish mechanical compatibility.', 'way/human-arc-mechanical/human-arc-method-44/'),
  ('human-arc-method-44', 'human-arc-mechanical', 439, '44. Public Health, Sanitation & Infrastructure Records', 'Complete the fictional map of water and waste exercise. Record evidence that a partner can check.', 'Set up: Fictional map of water and waste. Ask: Which records would distinguish a system fault from a rumor?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare anonymized fictional reports with a simple water and waste network diagram. Propose what records would establish a fault and which group should receive the maintenance report.', 'The work identifies questions for measurement and accountability. The scenario supplies no diagnosis or real emergency intervention.', 'way/human-learning-arc/'),
  ('human-arc-method-46', 'human-arc-digital', 440, '46. From Telegraph and Computing to Edge Networks', 'Complete the message timeline and failure diagram exercise. Record evidence that a partner can check.', 'Set up: Message timeline and failure diagram. Ask: Which changes depend on a new medium, and which on a new routing model?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Draw three systems: a point-to-point message relay, a central server and a local edge replica. Run the same school-library update through all three and remove one link in each trial.', 'The diagram explains where delivery stopped, which copies survived, and how the intended audience received a current version.', 'way/human-arc-digital/human-arc-method-21/'),
  ('human-arc-method-21', 'human-arc-digital', 441, '21. AI Prompting, Auditing & Hallucination Detection', 'Complete the three answers to a fictional source sheet exercise. Record evidence that a partner can check.', 'Set up: Three answers to a fictional source sheet. Ask: Which answer contains a claim its source never made?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare an answer, a deliberately flawed answer and their supplied source. Mark each individual claim as supported, contradicted or open. Write an improved prompt and a short correction.', 'A checked claim points to a source line. Keep the previous output and label the exact change in the correction.', 'way/human-arc-digital/human-arc-method-22/'),
  ('human-arc-method-22', 'human-arc-digital', 442, '22. Local Off-Grid Server & Mesh Networking', 'Complete the paper diagram of a consent-only local lab exercise. Record evidence that a partner can check.', 'Set up: Paper diagram of a consent-only local lab. Ask: Which records are available if the uplink stops?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Draw a three-device lab using your own test data. Use paper messages or a local-only classroom simulator to remove one path and recover an exported record. Note how data comes back after reconnection.', 'A strong design identifies which devices can still communicate, which records are offline, and who is authorized to see them.', 'way/human-arc-digital/human-arc-method-26/'),
  ('human-arc-method-26', 'human-arc-digital', 443, '26. Information Warfare & Propaganda Deconstruction', 'Complete the two headlines about one fictional event exercise. Record evidence that a partner can check.', 'Set up: Two headlines about one fictional event. Ask: Which words, omissions or images change the interpretation?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare two fictional headlines with the same underlying observation log. Highlight loaded wording, missing context and what the evidence cannot answer. Produce a short correction.', 'A supported correction quotes the relevant observation and identifies the precise change in framing. Keep claims about intent open unless there is evidence.', 'way/human-arc-digital/human-arc-method-27/'),
  ('human-arc-method-27', 'human-arc-digital', 444, '27. Cryptographic Provenance & Digital Ownership', 'Complete the two copies with a one-character edit exercise. Record evidence that a partner can check.', 'Set up: Two copies with a one-character edit. Ask: Which assertion does matching a saved digest prove?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Use two provided SHA-256 values or an approved classroom tool to compare a test file before and after changing one character. Record source, version, custody and digest separately.', 'A matching digest checks the bytes against the saved value. Authorship, rights and timestamps need their own trust evidence.', 'way/human-arc-digital/human-arc-method-45/'),
  ('human-arc-method-45', 'human-arc-digital', 445, '45. Data Stewardship, Accessibility & Recovery', 'Complete the local library backup practice exercise. Record evidence that a partner can check.', 'Set up: Local library backup practice. Ask: Can a second person restore and read the same record?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Create a test file, export a backup and provide a text-only or keyboard-operable view. Ask another participant to restore the exported file in a sandbox and read it with their chosen interface.', 'A passed recovery test identifies the source version, confirms the content, and demonstrates access with the supported interface.', 'way/human-learning-arc/'),
  ('human-arc-method-23', 'human-arc-future', 446, '23. Bio-Electric & Nervous System Sovereignty', 'Complete the attention-and-sensory-cue notebook exercise. Record evidence that a partner can check.', 'Set up: Attention-and-sensory-cue notebook. Ask: Do repeated observations support the change you noticed?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Complete two short, ordinary desk tasks in similar settings. Change one harmless factor, such as a quiet versus distracting sound environment, and record concentration with a simple rubric.', 'A personal result describes only these trials. Separate measured task performance, how you felt, and a clinical claim requiring other evidence.', 'way/human-arc-future/human-arc-method-24/'),
  ('human-arc-method-24', 'human-arc-future', 447, '24. Synthetic vs. Natural Material Forensics', 'Complete the known sample labels and microscope photos exercise. Record evidence that a partner can check.', 'Set up: Known sample labels and microscope photos. Ask: Which tests can identify a material, and which only sort clues?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Compare labeled wool, cotton and synthetic samples or their images. List visible clues, supplier labels and laboratory evidence under separate headings.', 'Appearance can narrow possibilities. A microfiber''s composition or additives need a suitable method and appropriate reference materials.', 'way/human-arc-future/human-arc-method-25/'),
  ('human-arc-method-25', 'human-arc-future', 448, '25. Zero-Waste & Closed-Loop Systems Design', 'Complete the repairable paper housing model exercise. Record evidence that a partner can check.', 'Set up: Repairable paper housing model. Ask: Which part can be replaced without throwing away the housing?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Create a cardboard model with a replaceable panel. Run a basic count of inputs, replacements, and scraps. Compare a repair and a total replacement scenario.', 'Measure waste in the same units over a fixed number of repair cycles. Show which scrap has a safe, practical next use.', 'way/human-arc-future/human-arc-method-28/'),
  ('human-arc-method-28', 'human-arc-future', 449, '28. Cross-Species & Ecological Communication', 'Complete the wildlife recordings and observation log exercise. Record evidence that a partner can check.', 'Set up: Wildlife recordings and observation log. Ask: What did the animal do before the observer named a feeling?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Use recorded wildlife observations. Tally visible actions and environmental changes on separate timelines. Compare two plausible explanations for one signal.', 'The report keeps observable movement or sound separate from inferred stress, intention or ecological cause.', 'way/human-arc-future/human-arc-method-29/'),
  ('human-arc-method-29', 'human-arc-future', 450, '29. Multi-Dimensional & Reverse-Order Processing', 'Complete the backward plan and forward test exercise. Record evidence that a partner can check.', 'Set up: Backward plan and forward test. Ask: Where do the two dependency lists disagree?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Start with a working paper bridge or local information kiosk. Work backward to its prerequisites, then run a forward check from the first input. Mark the first mismatch.', 'A repeatable test reaches the stated output. A backward plan identifies prerequisites and the forward run shows which ones worked.', 'way/human-arc-future/human-arc-method-30/'),
  ('human-arc-method-30', 'human-arc-future', 451, '30. Zero-Dependency Reset ("Burn to Zero & Rebuild")', 'Complete the 72-hour tabletop outage timeline exercise. Record evidence that a partner can check.', 'Set up: 72-hour tabletop outage timeline. Ask: What has to stay available first, and how would you restore it?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Simulate a 72-hour outage with a tabletop timeline or a short sandbox. Give the team cards for safe water, food, medication, emergency contact, accessibility, energy and communications. Rebuild the design around their dependencies.', 'A complete walkthrough retains essential services and identifies alternative suppliers and a fallback. Keep an explicit handoff and stop condition.', 'way/human-arc-future/human-arc-method-47/'),
  ('human-arc-method-47', 'human-arc-future', 452, '47. Water, Power, Food & Mutual Aid Planning', 'Complete the fictional neighborhood continuity board exercise. Record evidence that a partner can check.', 'Set up: Fictional neighborhood continuity board. Ask: Which supplies need coordination across households?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Track water, food, backup power and mutual-aid contacts in a tabletop scenario. Change one supply level and compare two plans for equitable access and repair.', 'A measurable plan identifies quantities, contact chains, supported access needs, and the trigger for asking for outside help.', 'way/human-arc-future/human-arc-method-48/'),
  ('human-arc-method-48', 'human-arc-future', 453, '48. Future Scenarios · Compare, Test & Revise', 'Complete the two possible futures for the same town exercise. Record evidence that a partner can check.', 'Set up: Two possible futures for the same town. Ask: What first observation would make each plan change?', 'Write your first prediction. Record the observation, historical inference, or future scenario that would test it.', 'Write two future scenarios using different resource and technology assumptions. Identify a useful early prototype and test it on paper with three evidence cards.', 'Each future is a possibility with assumptions and a change trigger. Record what can be tested today and what remains open.', 'way/human-learning-arc/')
